-- Generated from the current structured datasets in lib/.

-- Safe to re-run: rows are inserted or updated without deleting existing rows.

-- admin_allowlist is intentionally excluded; it requires real auth.users UUIDs.

BEGIN;

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    location = EXCLUDED.location,
    address = EXCLUDED.address,
    phone = EXCLUDED.phone,
    additional_phones = EXCLUDED.additional_phones,
    email = EXCLUDED.email,
    additional_emails = EXCLUDED.additional_emails,
    website = EXCLUDED.website,
    block = EXCLUDED.block,
    verified = EXCLUDED.verified,
    needs_verification = EXCLUDED.needs_verification,
    last_updated = EXCLUDED.last_updated,
    last_reviewed_at = EXCLUDED.last_reviewed_at,
    updated_at = now();

ON CONFLICT (entity_id, sort_order) DO UPDATE SET
    name = EXCLUDED.name,
    title = EXCLUDED.title,
    phone = EXCLUDED.phone,
    email = EXCLUDED.email,
    verified = EXCLUDED.verified;

ON CONFLICT (entity_id, sort_order) DO UPDATE SET
    label = EXCLUDED.label,
    url = EXCLUDED.url,
    checked_at = EXCLUDED.checked_at,
    supports = EXCLUDED.supports;

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    chairman = EXCLUDED.chairman,
    vice_chairman = EXCLUDED.vice_chairman,
    address = EXCLUDED.address,
    phone = EXCLUDED.phone,
    email = EXCLUDED.email,
    zone = EXCLUDED.zone,
    wards = EXCLUDED.wards,
    population = EXCLUDED.population,
    headquarters = EXCLUDED.headquarters,
    area = EXCLUDED.area,
    coordinates = EXCLUDED.coordinates,
    established = EXCLUDED.established,
    bio = EXCLUDED.bio,
    history = EXCLUDED.history,
    landmarks = EXCLUDED.landmarks,
    known_for = EXCLUDED.known_for,
    local_council_development_areas = EXCLUDED.local_council_development_areas,
    postal_code = EXCLUDED.postal_code;

ON CONFLICT (lga_id, sort_order) DO UPDATE SET
    name = EXCLUDED.name,
    title = EXCLUDED.title;

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    parent_lga_id = EXCLUDED.parent_lga_id,
    parent_lga_name = EXCLUDED.parent_lga_name,
    chairman = EXCLUDED.chairman,
    vice_chairman = EXCLUDED.vice_chairman,
    address = EXCLUDED.address,
    phone = EXCLUDED.phone,
    email = EXCLUDED.email,
    zone = EXCLUDED.zone,
    established = EXCLUDED.established,
    headquarters = EXCLUDED.headquarters,
    population = EXCLUDED.population,
    area = EXCLUDED.area,
    coordinates = EXCLUDED.coordinates,
    bio = EXCLUDED.bio,
    known_for = EXCLUDED.known_for;

ON CONFLICT (id) DO UPDATE SET
    lcda_id = EXCLUDED.lcda_id,
    sort_order = EXCLUDED.sort_order,
    name = EXCLUDED.name,
    description = EXCLUDED.description;

ON CONFLICT (id) DO UPDATE SET
    data = EXCLUDED.data,
    updated_at = now();

ON CONFLICT (id) DO UPDATE SET
    type = EXCLUDED.type,
    title = EXCLUDED.title,
    body = EXCLUDED.body,
    affected_lines = EXCLUDED.affected_lines,
    date = EXCLUDED.date,
    active = EXCLUDED.active,
    source_url = EXCLUDED.source_url,
    source_label = EXCLUDED.source_label;

COMMIT;

