INSERT INTO public.lgas (id, name, chairman, vice_chairman, address, phone, email, zone, wards, population, headquarters, area, coordinates, established, bio, history, landmarks, known_for, local_council_development_areas, postal_code)
VALUES
  ('agege', 'Agege', 'Hon. Ganiyu Egunjobi', 'Hon. Seun Adeyemi', 'Agege Local Government Secretariat, Old Abeokuta Road, Agege, Lagos', '+234-1-4930100', 'info@agege.lagosstate.gov.ng', 'Mainland', 11, '459,939', 'Agege', '22 km²', '{"lat":6.6193,"lng":3.3192}'::jsonb, '1976', 'Agege is a densely populated local government area located in the northwestern part of Lagos Mainland. Known for its vibrant commercial activities and diverse population, Agege is one of the most industrious communities in Lagos State. The area is a major hub for the textile and garment trade, with Agege market being one of the busiest in the state.', 'Agege was originally settled by Yoruba farmers and has grown significantly since the colonial era. It was officially recognised as a Local Government Area in 1976 during the local government reforms under General Murtala Muhammed. The area was historically known for cocoa farming before urbanisation transformed it into a commercial and residential district. Its proximity to the Lagos-Abeokuta Expressway made it a strategic gateway between Lagos and Ogun State.', '["Agege Market","Agege Stadium","Our Lady of Apostles Secondary School","Lagos-Abeokuta Expressway","Pen Cinema Roundabout"]'::jsonb, '["Textile & garment trade","Agege bread","Dense urban markets","Football (Shooting Stars)"]'::jsonb, '["Agege LCDA","Orile-Agege LCDA"]'::jsonb, '100283'),
  ('ajeromi-ifelodun', 'Ajeromi-Ifelodun', 'Hon. Fatai Ayoola', NULL, 'LG Secretariat, Hospital Road, Ajegunle, Lagos', '+234-1-4930200', 'info@ajeromi.lagosstate.gov.ng', 'Mainland', 10, '688,400', 'Ajegunle', '18 km²', '{"lat":6.4698,"lng":3.3541}'::jsonb, '1976', 'Ajeromi-Ifelodun is one of the most densely populated local government areas in Nigeria, home to the famous Ajegunle community. Despite its challenges, the area has produced some of Nigeria''s finest musicians, athletes and professionals. It is a vibrant melting pot of cultures with a strong sense of community identity.', 'Ajegunle''s origins trace back to the mid-20th century when workers drawn to the Lagos port and industrial zones settled in the area. The Ifelodun section has older roots tied to indigenous Yoruba settlements along the Lagos lagoon. In 1976 the two areas were merged into one LGA. Ajegunle became associated with working-class resilience and gave rise to legendary musicians including Daddy Showkey and Baba Fryo.', '["Ajegunle Market","Wharf Road","Boundary Bus Stop","International Trade Fair Proximity"]'::jsonb, '["Afrobeats & music culture","Boxing and football","Dense urban community","Cultural diversity"]'::jsonb, '["Ajeromi LCDA","Ifelodun LCDA"]'::jsonb, '102213'),
  ('alimosho', 'Alimosho', 'Hon. Jelili Sulaimon', NULL, 'LG Secretariat, Alimosho, Lagos', '+234-1-4930300', 'info@alimosho.lagosstate.gov.ng', 'Suburban', 12, '1,288,714', 'Alimosho', '233 km²', '{"lat":6.6058,"lng":3.2478}'::jsonb, '1991', 'Alimosho is the largest and most populous Local Government Area in Lagos State and in Nigeria. Spanning over 233 square kilometres, it encompasses diverse communities including Egbe, Idimu, Ipaja, Igando and Satellite Town. The area is a major residential hub with a booming real estate market and growing commercial activity.', 'Alimosho was carved out as a separate LGA in 1991 from the old Agege LGA as part of the military government''s local government restructuring. Before urbanisation, the area was largely agrarian with small Yoruba farming settlements. The construction of the Lagos-Abeokuta Expressway and later the development of estates such as Jakande Estate and Satellite Town spurred massive population growth. Today it hosts over 1.2 million residents making it the most populous LGA in Nigeria.', '["Egbe-Idimu Market","Jakande Estate","Satellite Town","Ipaja Road","Akowonjo Roundabout","Command Secondary School"]'::jsonb, '["Largest LGA in Nigeria","Massive residential estates","Real estate growth","Igando market"]'::jsonb, '["Egbe-Idimu LCDA","Igando-Ikotun LCDA","Ikotun-Igando LCDA","Isolo LCDA","Mosan-Okunola LCDA"]'::jsonb, '100265'),
  ('amuwo-odofin', 'Amuwo-Odofin', 'Hon. Engr. Sola Abiodun', NULL, 'LG Secretariat, Mile 2, Lagos', '+234-1-4930400', 'info@amuwo.lagosstate.gov.ng', 'Mainland', 10, '317,720', 'Mile 2', '140 km²', '{"lat":6.4728,"lng":3.2944}'::jsonb, '1991', 'Amuwo-Odofin is a strategically located LGA covering Mile 2, Festac Town, Satellite Town and the Atlas Cove petroleum facility. It is home to the iconic FESTAC Town — the site of the 1977 Second World Black and African Festival of Arts and Culture — which remains one of Africa''s most ambitious housing projects.', 'Amuwo-Odofin was created in 1991. Its most significant historical event was hosting FESTAC ''77, a pan-African cultural festival that brought together over 17,000 artists, writers and performers from 59 African nations and the diaspora. The Festac housing estate built for the festival became one of Lagos''s most organised residential communities. The LGA also hosts the Atlas Cove petroleum depot, a critical fuel storage and distribution hub for Nigeria.', '["FESTAC Town","Mile 2 Bus Terminal","Atlas Cove Petroleum Depot","FESTAC 77 Monument","International Trade Fair Complex"]'::jsonb, '["FESTAC ''77 heritage","Organised residential estates","Mile 2 transport hub","Atlas Cove fuel depot"]'::jsonb, '["Amuwo-Odofin LCDA","Oriade LCDA"]'::jsonb, '102102'),
  ('apapa', 'Apapa', 'Hon. Idowu Ganiyu', NULL, 'LG Secretariat, Burma Road, Apapa, Lagos', '+234-1-4930500', 'info@apapa.lagosstate.gov.ng', 'Mainland', 8, '217,362', 'Apapa', '20 km²', '{"lat":6.4481,"lng":3.3591}'::jsonb, '1976', 'Apapa is Nigeria''s premier port city and the commercial gateway of the nation. Home to the Apapa Port — one of the busiest seaports in West Africa — the LGA is the heartbeat of Nigeria''s import and export trade. Despite its industrial character, Apapa also houses upscale residential estates and important federal institutions.', 'Apapa''s development began in earnest during the colonial period when the British constructed the first deep-water wharf in 1913, transforming Lagos into a major maritime hub. The port expanded significantly after Nigerian independence and today handles billions of dollars in trade annually. Apapa was among the earliest local government areas formally established in 1976. Congestion around the port has been a long-standing infrastructure challenge that multiple administrations have worked to address.', '["Apapa Port (NPA)","Tin Can Island Port","Apapa-Oshodi Expressway","Apapa Club","Nigerian Breweries HQ","NICON Hilton (historical)"]'::jsonb, '["Largest seaport in West Africa","Industrial and commercial hub","Import/export trade","Petroleum tanker traffic"]'::jsonb, '["Apapa-Iganmu LCDA"]'::jsonb, '101245'),
  ('badagry', 'Badagry', 'Hon. Folorunsho Ambrose', NULL, 'LG Secretariat, Badagry, Lagos', '+234-1-4930600', 'info@badagry.lagosstate.gov.ng', 'Suburban', 11, '241,093', 'Badagry', '1,866 km²', '{"lat":6.4154,"lng":2.8895}'::jsonb, '1976', 'Badagry is one of the oldest and most historically significant towns in Nigeria, located on the border with the Republic of Benin. A former major slave trade port, the town is now a centre for heritage tourism with numerous museums, slave route relics and colonial monuments. Its vast coastline and lagoon system make it one of Lagos State''s most scenic destinations.', 'Badagry served as a major transit point of the transatlantic slave trade from the 17th to 19th centuries, with an estimated 500,000 enslaved Africans passing through the Point of No Return. The first storey building in Nigeria was built here in 1845 by Rev. Benjamin Tregaskis. Christianity also entered Nigeria through Badagry when the Rev. Thomas Birch Freeman arrived in 1842. The town''s history of slavery, colonial resistance and cultural preservation makes it one of Nigeria''s most important heritage sites.', '["Slave Route / Point of No Return","Badagry Heritage Museum","First Storey Building in Nigeria","Gberefu Beach","Vlekete Slave Market","Holy Cross Cathedral (1863)"]'::jsonb, '["Slave trade heritage","Historical tourism","Border town with Benin Republic","Fishing communities","Coconut plantations"]'::jsonb, '["Badagry East LCDA","Badagry West LCDA"]'::jsonb, '112101'),
  ('epe', 'Epe', 'Hon. Suraj Olaposi Edu', NULL, 'LG Secretariat, Epe, Lagos', '+234-1-4930700', 'info@epe.lagosstate.gov.ng', 'Suburban', 10, '200,273', 'Epe', '1,390 km²', '{"lat":6.5864,"lng":3.9779}'::jsonb, '1976', 'Epe is a historic town and LGA situated on the northern shores of the Lekki Lagoon, known for its fishing heritage and growing status as an emerging smart city. The Epe Resort and the Lekki Free Zone nearby have positioned the area as a major economic frontier for Lagos State, with major industrial and real estate investments transforming its landscape.', 'Epe has a deep-rooted history tied to the Ijebu Yoruba. In 1853, Oba Kosoko, a former Oba of Lagos, was exiled to Epe after a conflict with the British, establishing a royal court that shaped the town''s political culture. The town later became a British protectorate before being incorporated into the Lagos Colony. Epe''s fishing traditions remain vibrant and the annual Ojude Oba festival is one of the most celebrated cultural events in the region.', '["Epe Lagoon","Epe Resort & Spa","Lekki Free Zone","Ojude Oba Festival Grounds","Royal Palace of Epe","Epe Fish Market"]'::jsonb, '["Fishing & seafood","Ojude Oba festival","Lekki Free Zone proximity","Emerging smart city","Lagoon tourism"]'::jsonb, '["Epe LCDA","Ikosi-Ejinrin LCDA"]'::jsonb, '106101'),
  ('eti-osa', 'Eti-Osa', 'Hon. Segun Oni', NULL, 'LG Secretariat, Lekki Phase 1, Lagos', '+234-1-4930800', 'info@etiosa.lagosstate.gov.ng', 'Island', 10, '324,418', 'Lekki', '468 km²', '{"lat":6.4294,"lng":3.5958}'::jsonb, '1991', 'Eti-Osa is the wealthiest and most cosmopolitan LGA in Lagos State, encompassing Victoria Island, Ikoyi, Lekki, Ajah and Sangotedo. It is home to the highest concentration of multinational companies, luxury estates, embassies and fine dining establishments in Nigeria. The ongoing Eko Atlantic City development — a brand new city rising from the Atlantic Ocean — is located within its jurisdiction.', 'Eti-Osa was carved out as an LGA in 1991. Victoria Island was developed by the British colonial administration as an exclusive residential area for expatriates and senior officials, and this character largely persisted after independence. Ikoyi similarly developed as an elite enclave. The Lekki axis, which was largely forested peninsula until the 1990s, has since become one of the fastest-growing real estate markets in Africa, driven by private investment and the Lagos State Master Plan.', '["Victoria Island","Ikoyi","Lekki Phase 1","Eko Atlantic City","Bar Beach","National Museum Lagos","Nike Art Gallery","Oniru Royal Estate"]'::jsonb, '["Luxury real estate","Multinational headquarters","Eko Atlantic City","Lekki-Epe Expressway","Nightlife & fine dining"]'::jsonb, '["Ikoyi-Obalende LCDA","Iru-Victoria Island LCDA","Lagos Island East LCDA"]'::jsonb, '101233'),
  ('ibeju-lekki', 'Ibeju-Lekki', 'Hon. Muyiwa Ibile', NULL, 'LG Secretariat, Akodo Ise, Lagos', '+234-1-4930900', 'info@ibejulekki.lagosstate.gov.ng', 'Suburban', 10, '117,103', 'Akodo', '1,126 km²', '{"lat":6.4353,"lng":3.8087}'::jsonb, '1991', 'Ibeju-Lekki is the fastest-growing LGA in Nigeria and arguably on the African continent. Home to the Dangote Refinery — the largest single-train petroleum refinery in the world — the Lekki Free Zone, Lekki Deep Sea Port and the proposed Lekki International Airport, the LGA is set to become a major industrial powerhouse. Its pristine beaches and lagoons also make it a tourism destination.', 'Ibeju-Lekki was created in 1991 from parts of the old Epe LGA. For decades it was sparsely populated with small fishing and farming communities. The declaration of the Lekki Free Trade Zone in 2006 marked the turning point, attracting hundreds of billions in foreign direct investment. The Dangote Refinery, which has a capacity of 650,000 barrels per day, broke ground in 2016 and is now transforming not just the LGA but the entire Nigerian petroleum sector.', '["Dangote Refinery","Lekki Deep Sea Port","Lekki Free Zone","La Campagne Tropicana Beach","Eleko Beach","Proposed Lekki International Airport"]'::jsonb, '["Dangote Refinery","Lekki Free Zone","Fastest-growing LGA in Nigeria","Pristine beaches","Massive FDI inflows"]'::jsonb, '["Ibeju LCDA","Lekki LCDA"]'::jsonb, '106104'),
  ('ifako-ijaiye', 'Ifako-Ijaiye', 'Hon. Usman Hamzat', NULL, 'LG Secretariat, Ogba, Lagos', '+234-1-4931000', 'info@ifako.lagosstate.gov.ng', 'Mainland', 11, '423,988', 'Ogba', '81 km²', '{"lat":6.6463,"lng":3.3404}'::jsonb, '1991', 'Ifako-Ijaiye is a predominantly residential LGA in the northwestern part of Lagos Mainland, covering Ogba, Ifako, Ijaiye and Agbado communities. The Ogba axis in particular has become one of Lagos''s most desirable middle-class residential areas, with numerous estates, schools and shopping facilities that have grown steadily over the past two decades.', 'Ifako-Ijaiye was created as a separate LGA in 1991 from the old Agege Local Government. The Agbado area, on the border with Ogun State, has historical roots as a railway junction town dating back to the colonial construction of the Lagos-Kano railway line. The LGA''s transformation into a residential zone accelerated in the 1980s and 1990s as Lagosians sought alternatives to crowded Island and central Mainland communities.', '["Ogba Shopping Mall","Agbado Railway Station","Ijaiye Market","Agidingbi Industrial Area","Command Children School"]'::jsonb, '["Middle-class residential estates","Ogba shopping district","Railway junction history","Mixed-use urban development"]'::jsonb, '["Ifako-Ijaye LCDA","Ojokoro LCDA"]'::jsonb, '100272'),
  ('ikeja', 'Ikeja', 'Hon. Mojeed Balogun', NULL, 'LG Secretariat, Oba Akinjobi Road, Ikeja, Lagos', '+234-1-4931100', 'info@ikeja.lagosstate.gov.ng', 'Mainland', 11, '313,196', 'Ikeja', '46 km²', '{"lat":6.595,"lng":3.3381}'::jsonb, '1976', 'Ikeja is the capital of Lagos State and the administrative headquarters of Lagos State Government. Home to the Murtala Muhammed International Airport, the Lagos State Secretariat at Alausa, the Lagos State House of Assembly and numerous government institutions, Ikeja is the political nerve centre of Nigeria''s most commercially significant state. The Ikeja GRA remains one of the most exclusive residential districts in Nigeria.', 'Ikeja''s history as a seat of government dates to the colonial era when the British established administrative offices in the area due to its strategic location inland from Lagos Island. After Nigerian independence, Ikeja Airport (later renamed after General Murtala Muhammed) became the primary international gateway into Nigeria. When Lagos State was created in 1967, Ikeja was designated the state capital, a role it continues to fulfil. The 2002 Ikeja Military Cantonment explosion remains one of the most devastating disasters in the LGA''s history.', '["Murtala Muhammed International Airport","Lagos State Secretariat, Alausa","Ikeja GRA","Computer Village","Lagos State House of Assembly","Sheraton Lagos Hotel"]'::jsonb, '["Lagos State capital","International Airport","Computer Village (tech hub)","Government institutions","Ikeja GRA"]'::jsonb, '["Ojodu LCDA","Onigbongbo LCDA"]'::jsonb, '100001'),
  ('ikorodu', 'Ikorodu', 'Hon. Wasiu Adesanya', NULL, 'LG Secretariat, Lagos Road, Ikorodu, Lagos', '+234-1-4931200', 'info@ikorodu.lagosstate.gov.ng', 'Suburban', 12, '535,619', 'Ikorodu', '941 km²', '{"lat":6.6194,"lng":3.5061}'::jsonb, '1976', 'Ikorodu is a rapidly growing LGA located on the northeastern shore of Lagos Lagoon. Once a quiet town known for its fishing and farming communities, Ikorodu has experienced explosive growth driven by its proximity to Lagos Island via the lagoon ferry and the Lagos-Ikorodu Road. It is increasingly attracting manufacturing industries and residential developers seeking land alternatives to congested Lagos Mainland.', 'Ikorodu has ancient roots as a Yoruba town whose people are closely related to the Ijebu-Remo of Ogun State. The town resisted British colonial incursions in the late 19th century before being brought under colonial rule. The Ikorodu water works, built in the early 20th century, was one of the first modern water supply systems outside Lagos Island. The LGA has grown tremendously since the construction of the Ikorodu expressway and the expansion of ferry services across the lagoon.', '["Ikorodu Ferry Terminal","Lagos Lagoon Waterfront","Ijede Fishing Community","Ikorodu General Hospital","Lagos-Ikorodu Road"]'::jsonb, '["Lagoon ferry services","Growing manufacturing zone","Fishing communities","Affordable real estate","Ikorodu traditional festival"]'::jsonb, '["Ikorodu North LCDA","Ikorodu West LCDA","Igbogbo-Bayeku LCDA","Imota LCDA","Ikosi-Isheri LCDA"]'::jsonb, '104101'),
  ('kosofe', 'Kosofe', 'Hon. Moyosore Ogunlewe', NULL, 'LG Secretariat, Kosofe, Lagos', '+234-1-4931300', 'info@kosofe.lagosstate.gov.ng', 'Mainland', 11, '665,393', 'Kosofe', '81 km²', '{"lat":6.5833,"lng":3.4167}'::jsonb, '1991', 'Kosofe LGA covers the areas of Ketu, Ojota, Mile 12, Alapere and Ogudu, making it one of the key transportation and commercial nodes on the Lagos Mainland. Mile 12 International Market — one of the largest fresh produce markets in West Africa — is located here, serving as the primary fresh food distribution hub for Lagos and surrounding states.', 'Kosofe was created in 1991 from the old Mushin LGA. The area''s growth is closely tied to the construction of the Lagos-Ibadan Expressway and the development of Mile 12 as a major commercial hub. Ketu has historical roots as a Yoruba settlement and is named after the ancient Ketu Kingdom in present-day Benin Republic from which some of its founders migrated. The area became a major entry point for goods and people from eastern and northern Nigeria.', '["Mile 12 Market","Ketu Bus Terminal","Ojota Bus Terminal","Ogudu GRA","Alapere Estate","NASFAT Headquarters"]'::jsonb, '["Mile 12 produce market","Major bus terminals (Ketu/Ojota)","Fresh food distribution hub","Multicultural population"]'::jsonb, '["Kosofe LCDA","Agboyi-Ketu LCDA"]'::jsonb, '100215'),
  ('lagos-island', 'Lagos Island', 'Hon. Idris Aregbe', NULL, 'LG Secretariat, Igbosere Road, Lagos Island, Lagos', '+234-1-4931400', 'info@lagosisland.lagosstate.gov.ng', 'Island', 11, '209,437', 'Lagos Island', '8 km²', '{"lat":6.4531,"lng":3.3958}'::jsonb, '1976', 'Lagos Island is the historic heart of Lagos — the original settlement from which the entire city grew. It hosts the Central Business District, the Balogun Market (one of the largest in West Africa), the Lagos Stock Exchange, the CBN head office and the seat of the old colonial administration. Despite being one of the smallest LGAs by area, it has the highest commercial density in Nigeria.', 'Lagos Island''s history spans over 400 years. According to tradition, the Awori people first settled on the island before the Bini Kingdom exerted influence and installed Oba Oduduwa''s lineage as royalty around the 16th century. Portuguese traders arrived in the 15th century, giving the area its name ''Lagos'' (meaning ''lakes''). The British formally colonised Lagos in 1861 making it a Crown Colony. Lagos Island served as the capital of colonial Nigeria until the capital moved to Abuja in 1991.', '["Eko Bridge","Carter Bridge","Balogun Market","Lagos Stock Exchange","Central Bank of Nigeria HQ","Oba''s Palace (Iga Idunganran)","National Museum Lagos","Tafawa Balewa Square"]'::jsonb, '["Historic heart of Lagos","Financial and commercial hub","Balogun Market","Oba''s Palace","Nigeria''s oldest city core"]'::jsonb, '["Lagos Island East LCDA","Ikoyi-Obalende LCDA"]'::jsonb, '101001'),
  ('lagos-mainland', 'Lagos Mainland', 'Hon. Adewale Adegoke', NULL, 'LG Secretariat, Yaba, Lagos', '+234-1-4931500', 'info@lagosmainiland.lagosstate.gov.ng', 'Mainland', 11, '317,720', 'Ebute Metta', '33 km²', '{"lat":6.5095,"lng":3.3711}'::jsonb, '1976', 'Lagos Mainland LGA covers Yaba, Ebute Metta, Oyingbo and Makoko — some of the most culturally rich and historically significant communities in Lagos. Yaba is Nigeria''s premier technology hub, home to CcHub, dozens of startups and the University of Lagos. Makoko, the famous floating community on the lagoon, is one of the most photographed urban settlements in Africa.', 'Lagos Mainland was the colonial administration''s link between Lagos Island and the interior of Nigeria. Ebute Metta developed as a railway terminus town after the construction of the Lagos-Kano railway in 1901. Yaba was developed by the British as a residential area for civil servants and intellectuals, and later housed the Yaba Higher College (1932), the precursor to the University of Lagos. The area has always been associated with education, activism and intellectual life in Nigeria.', '["University of Lagos","Yaba Tech (YABATECH)","Makoko Floating Community","Yaba Market","Lagos General Hospital","National Theatre","CcHub Nigeria"]'::jsonb, '["Yaba tech ecosystem","University of Lagos","Makoko floating village","Railway history","Education hub"]'::jsonb, '["Yaba LCDA"]'::jsonb, '101212'),
  ('mushin', 'Mushin', 'Hon. Bamidele Onaolapo', NULL, 'LG Secretariat, Mushin, Lagos', '+234-1-4931600', 'info@mushin.lagosstate.gov.ng', 'Mainland', 11, '633,009', 'Mushin', '27 km²', '{"lat":6.5277,"lng":3.3561}'::jsonb, '1976', 'Mushin is one of the most densely populated and commercially active LGAs on the Lagos Mainland. Known for its bustling markets, auto-parts trade and vibrant street culture, Mushin has a strong working-class identity and has produced many of Nigeria''s most celebrated artists, musicians and entrepreneurs. The area is synonymous with the Alaba and Ladipo markets — major auto parts trading hubs.', 'Mushin was originally a farming settlement on the outskirts of Lagos before rapid urban migration transformed it from the 1940s onwards. It became a major destination for migrants from Yoruba and Igbo communities seeking work in Lagos. The area developed a reputation for both vibrant commerce and social challenges. In the 1970s and 80s, Mushin was associated with area boys and street gangs, but also with remarkable creative output including contributions to Jùjú and Afrobeats music.', '["Ladipo Market (Auto Parts)","Mushin Market","Idi-Oro Bus Stop","Papa Ajao Market","Idi-Araba Hospital Area"]'::jsonb, '["Auto parts trade (Ladipo)","Vibrant street markets","Music and nightlife culture","Working-class heritage"]'::jsonb, '["Mushin LCDA","Odi-Olowo/Ojuwoye LCDA"]'::jsonb, '100283'),
  ('ojo', 'Ojo', 'Hon. Abdulkadir Maji', NULL, 'LG Secretariat, Ojo, Lagos', '+234-1-4931700', 'info@ojo.lagosstate.gov.ng', 'Mainland', 11, '598,071', 'Ojo', '177 km²', '{"lat":6.4698,"lng":3.2067}'::jsonb, '1976', 'Ojo LGA is a large and diverse local government area along the Lagos Badagry Expressway, encompassing military cantonments, beach communities, and the campuses of Lagos State University and Adeniran Ogunsanya College of Education. The area is also home to the Ojo Military Cantonment — one of the largest military bases in Nigeria — and its coastline along the Bight of Benin offers scenic Atlantic beaches.', 'Ojo has historically been a strategic military and maritime location. The British colonial authorities established a military base here in the early 20th century that grew into the present-day Nigerian Army cantonment. After independence, Ojo emerged as a significant educational centre with LASU establishing its main campus along the expressway. The area''s coastline has been used for fishing for centuries by the indigenous Awori communities.', '["Lagos State University (LASU)","Ojo Military Cantonment","Badagry Expressway","Ojo Beach","Adeniran Ogunsanya College of Education"]'::jsonb, '["LASU campus","Military cantonment","Atlantic coastline","Expressway communities","Educational institutions"]'::jsonb, '["Ojo LCDA","Oto-Awori LCDA"]'::jsonb, '102101'),
  ('oshodi-isolo', 'Oshodi-Isolo', 'Hon. Bolaji Muse-Ariyibi', NULL, 'LG Secretariat, Isolo, Lagos', '+234-1-4931800', 'info@oshodi.lagosstate.gov.ng', 'Mainland', 12, '676,366', 'Isolo', '39 km²', '{"lat":6.5354,"lng":3.338}'::jsonb, '1991', 'Oshodi-Isolo is one of the most commercially active transit LGAs in Lagos, home to the famous Oshodi Market and the critical Oshodi transport interchange that connects bus routes across the city. The Isolo industrial estate is one of the oldest and largest in Lagos, housing hundreds of manufacturing and processing firms. The ongoing Oshodi-Apapa Expressway and Oshodi-Abule Egba BRT corridor pass through the LGA.', 'Oshodi developed as a major transport junction from the early 20th century due to its position along key road and rail arteries. The Oshodi Market grew organically as traders exploited the area''s transit character. Isolo Industrial Estate was developed by the Lagos State Government in the 1970s as part of an industrialisation drive. The LGA was formally created in 1991. The BRT expansion and road rehabilitation under Governor Fashola in the late 2000s dramatically transformed Oshodi''s urban character.', '["Oshodi Transport Interchange","Oshodi Market","Isolo Industrial Estate","Oshodi-Apapa Expressway","FESTAC Junction","Old Toll Gate Area"]'::jsonb, '["Major transport hub","Oshodi market","Isolo industrial estate","BRT corridor","Commercial density"]'::jsonb, '["Isolo LCDA","Ejigbo LCDA"]'::jsonb, '100213'),
  ('shomolu', 'Shomolu', 'Hon. Kehinde Oloyede', NULL, 'LG Secretariat, Shomolu, Lagos', '+234-1-4931900', 'info@shomolu.lagosstate.gov.ng', 'Mainland', 11, '402,673', 'Shomolu', '13 km²', '{"lat":6.5356,"lng":3.3861}'::jsonb, '1991', 'Shomolu LGA encompasses the communities of Shomolu, Bariga, Gbagada and Pedro. The area has a strong identity tied to education, with several respected secondary schools and proximity to the University of Lagos. Gbagada is one of Lagos''s most sought-after residential areas for the middle and upper-middle class, with good infrastructure and proximity to both the Island and Mainland.', 'Shomolu was created as a separate LGA in 1991 from the former Lagos Mainland LGA. Bariga has deep historical connections to Lagos''s early urban growth, with the community developing alongside the expansion of the railway. The area is associated with some of Nigeria''s most prominent educational and media institutions. Gbagada''s development as an upscale area accelerated in the late 1990s and 2000s as real estate investors developed estates targeting professionals and diaspora returnees.', '["Gbagada General Hospital","Anthony Bus Stop","Shomolu Market","Bariga Sports Complex","Lagos TV (LTV) Headquarters","Third Mainland Bridge Access"]'::jsonb, '["Gbagada residential estate","Media institutions","Education corridor","Third Mainland Bridge proximity","Middle-class residential area"]'::jsonb, '["Shomolu LCDA","Bariga LCDA"]'::jsonb, '102001'),
  ('surulere', 'Surulere', 'Hon. Tajudeen Ajide', NULL, 'LG Secretariat, Surulere, Lagos', '+234-1-4932000', 'info@surulere.lagosstate.gov.ng', 'Mainland', 11, '503,975', 'Surulere', '23 km²', '{"lat":6.4969,"lng":3.3481}'::jsonb, '1976', 'Surulere is one of Lagos''s most iconic and culturally vibrant LGAs. Home to the National Stadium — the largest in Nigeria — the National Theatre, the Lagos University Teaching Hospital and the famous Adeniran Ogunsanya Street, Surulere blends sports, arts, healthcare and commerce into a unique urban identity. It remains one of the most beloved residential communities for Lagos''s creative and professional class.', 'Surulere was developed as a planned residential estate in the 1950s to house the growing Lagos population. Its name in Yoruba means ''patience yields reward''. The National Stadium was built for the second All-Africa Games in 1973 and hosted several iconic events including the 1977 FESTAC. LUTH was established in 1962 as a teaching affiliate of the University of Lagos. Surulere''s creative output — from literature to Afrobeats — has been immense, with Fela Anikulapo-Kuti living and performing in the area.', '["National Stadium Lagos","National Theatre","LUTH (Lagos University Teaching Hospital)","Adeniran Ogunsanya Street","Shitta-Bey Mosque","Teslim Balogun Stadium"]'::jsonb, '["National Stadium","National Theatre","Afrobeats culture (Fela Kuti)","LUTH healthcare","Creative class residential area"]'::jsonb, '["Surulere LCDA","Itire-Ikate LCDA"]'::jsonb, '101241')
