VALUES
  ('agege-lcda', 'Agege LCDA', 'agege', 'Agege', 'Hon. Seun Adeyemi', NULL, 'Agege LCDA Secretariat, Old Abeokuta Road, Agege, Lagos', '+234-1-4930110', 'info@agege-lcda.lagosstate.gov.ng', 'Mainland', '2002', 'Agege', '245,000', '12 km²', '{"lat":6.6193,"lng":3.3192}'::jsonb, 'Agege LCDA covers the core Agege township, one of the most densely populated council areas in Lagos. It is a major hub for the textile trade, garment manufacturing and street food culture. The area has a deeply rooted Muslim and Christian population living harmoniously.', '["Textile & garment trade","Agege bread","Pen Cinema","Dense urban market"]'::jsonb),
  ('orile-agege-lcda', 'Orile-Agege LCDA', 'agege', 'Agege', 'Hon. Kazeem Adewale', NULL, 'Orile-Agege LCDA Secretariat, Agege, Lagos', '+234-1-4930120', NULL, 'Mainland', '2002', 'Orile-Agege', '215,000', '10 km²', '{"lat":6.61,"lng":3.305}'::jsonb, 'Orile-Agege LCDA serves the southwestern portion of the old Agege LGA. The area is characterised by a mix of residential estates and informal settlements with strong community associations and youth groups.', '["Residential communities","Light industry","Community associations"]'::jsonb),
  ('ajeromi-lcda', 'Ajeromi LCDA', 'ajeromi-ifelodun', 'Ajeromi-Ifelodun', 'Hon. Bola Nwachukwu', NULL, 'Ajeromi LCDA Secretariat, Ajegunle, Lagos', '+234-1-4930210', NULL, 'Mainland', '2002', 'Ajegunle', '380,000', '10 km²', '{"lat":6.4698,"lng":3.3541}'::jsonb, 'Ajeromi LCDA covers the core Ajegunle district — one of the most densely populated urban communities in West Africa. Despite infrastructural challenges, the area is famous for producing world-class musicians, athletes and entrepreneurs.', '["Music culture","Boxing","Wharf Road","Urban resilience"]'::jsonb),
  ('ifelodun-lcda', 'Ifelodun LCDA', 'ajeromi-ifelodun', 'Ajeromi-Ifelodun', 'Hon. Wasiu Ogunbayo', NULL, 'Ifelodun LCDA Secretariat, Ajeromi, Lagos', '+234-1-4930220', NULL, 'Mainland', '2002', 'Ifelodun', NULL, NULL, '{"lat":6.46,"lng":3.34}'::jsonb, 'Ifelodun LCDA covers the eastern section of the Ajeromi-Ifelodun LGA bordering Apapa. The area has significant fishing and market communities.', '["Fishing communities","Market trade","Waterfront access"]'::jsonb),
  ('egbe-idimu-lcda', 'Egbe-Idimu LCDA', 'alimosho', 'Alimosho', 'Hon. Ganiyu Kola-Daisi', NULL, 'Egbe-Idimu LCDA Secretariat, Egbe, Lagos', '+234-1-4930310', NULL, 'Suburban', '2002', 'Egbe', '220,000', '35 km²', '{"lat":6.57,"lng":3.29}'::jsonb, 'Egbe-Idimu LCDA is a fast-growing residential council area covering Egbe and Idimu communities. It has experienced significant real estate development and has good road connectivity to the Lagos-Ibadan Expressway.', '["Residential estates","Egbe Market","Church communities"]'::jsonb),
  ('igando-ikotun-lcda', 'Igando-Ikotun LCDA', 'alimosho', 'Alimosho', 'Hon. Moshood Adekunle', NULL, 'Igando-Ikotun LCDA Secretariat, Igando, Lagos', '+234-1-4930320', NULL, 'Suburban', '2002', 'Igando', NULL, NULL, '{"lat":6.56,"lng":3.26}'::jsonb, 'Igando-Ikotun LCDA covers the Igando and Ikotun communities, major residential and commercial areas in the Alimosho axis. Igando Market is one of the largest in the area.', '["Igando Market","Residential estates","Community trade"]'::jsonb),
  ('ikotun-igando-lcda', 'Ikotun-Igando LCDA', 'alimosho', 'Alimosho', 'Hon. Segun Olatunbosun', NULL, 'Ikotun-Igando LCDA Secretariat, Ikotun, Lagos', '+234-1-4930330', NULL, 'Suburban', '2002', 'Ikotun', NULL, NULL, '{"lat":6.55,"lng":3.25}'::jsonb, 'Ikotun-Igando LCDA is a twin council area serving the densely settled Ikotun-Igando corridor. The area has vibrant street markets and growing infrastructure.', '["Street markets","Residential growth","Transport corridor"]'::jsonb),
  ('isolo-lcda', 'Isolo LCDA', 'alimosho', 'Alimosho', 'Hon. Tunde Bello', NULL, 'Isolo LCDA Secretariat, Isolo, Lagos', '+234-1-4930340', NULL, 'Suburban', '2002', 'Isolo', NULL, NULL, '{"lat":6.5354,"lng":3.3}'::jsonb, 'Isolo LCDA is a major industrial and residential council area. It hosts Isolo Industrial Estate, one of the oldest in Lagos, alongside large residential communities along Oshodi-Apapa Expressway.', '["Isolo Industrial Estate","Manufacturing hub","Residential estates"]'::jsonb),
  ('mosan-okunola-lcda', 'Mosan-Okunola LCDA', 'alimosho', 'Alimosho', 'Hon. Bolaji Sanusi', NULL, 'Mosan-Okunola LCDA Secretariat, Ipaja, Lagos', '+234-1-4930350', NULL, 'Suburban', '2002', 'Ipaja', NULL, NULL, '{"lat":6.61,"lng":3.23}'::jsonb, 'Mosan-Okunola LCDA covers the Ipaja, Mosan and Okunola communities in the far western part of Alimosho. The area borders Ogun State and has a large commuter population.', '["Ipaja Road corridor","Border communities","Commuter hub"]'::jsonb),
  ('amuwo-odofin-lcda', 'Amuwo-Odofin LCDA', 'amuwo-odofin', 'Amuwo-Odofin', 'Hon. Adeola Ogunyemi', NULL, 'Amuwo-Odofin LCDA Secretariat, Mile 2, Lagos', '+234-1-4930410', NULL, 'Mainland', '2002', 'Mile 2', NULL, NULL, '{"lat":6.4728,"lng":3.2944}'::jsonb, 'Amuwo-Odofin LCDA covers the northern part of the LGA including Mile 2, Ojo Barracks and the International Trade Fair Complex vicinity. It is a key transport hub connecting Lagos Island and the Mainland.', '["Mile 2 transport hub","Trade Fair proximity","Military barracks"]'::jsonb),
  ('oriade-lcda', 'Oriade LCDA', 'amuwo-odofin', 'Amuwo-Odofin', 'Hon. Adewale Adisa', NULL, 'Oriade LCDA Secretariat, Satellite Town, Lagos', '+234-1-4930420', NULL, 'Mainland', '2002', 'Satellite Town', NULL, NULL, '{"lat":6.45,"lng":3.27}'::jsonb, 'Oriade LCDA covers Satellite Town and surrounding communities in the southern part of Amuwo-Odofin. The area has well-planned residential estates and petrochemical industry proximity.', '["Satellite Town estates","Planned residential areas","Atlas Cove proximity"]'::jsonb),
  ('apapa-iganmu-lcda', 'Apapa-Iganmu LCDA', 'apapa', 'Apapa', 'Hon. Seun Ogunbanjo', NULL, 'Apapa-Iganmu LCDA Secretariat, Apapa, Lagos', '+234-1-4930510', NULL, 'Mainland', '2002', 'Apapa', NULL, NULL, '{"lat":6.4481,"lng":3.3591}'::jsonb, 'Apapa-Iganmu LCDA covers the port district and Iganmu community. It sits at the heart of Nigeria''s maritime commerce, with the Apapa and Tin Can Island ports within its jurisdiction.', '["Port activities","Iganmu industrial area","Maritime trade","Apapa GRA"]'::jsonb),
  ('badagry-east-lcda', 'Badagry East LCDA', 'badagry', 'Badagry', 'Hon. Gafar Fadipe', NULL, 'Badagry East LCDA Secretariat, Badagry, Lagos', '+234-1-4930610', NULL, 'Suburban', '2002', 'Badagry', NULL, NULL, '{"lat":6.4154,"lng":2.91}'::jsonb, 'Badagry East LCDA covers the eastern portion of the historic Badagry town including the slave heritage sites and coastal fishing communities.', '["Slave trade heritage","Coastal fishing","Heritage tourism"]'::jsonb),
  ('badagry-west-lcda', 'Badagry West LCDA', 'badagry', 'Badagry', 'Hon. Michael Olawale', NULL, 'Badagry West LCDA Secretariat, Seme, Lagos', '+234-1-4930620', NULL, 'Suburban', '2002', 'Seme', NULL, NULL, '{"lat":6.35,"lng":2.72}'::jsonb, 'Badagry West LCDA covers the border communities toward the Republic of Benin, including the Seme border crossing. It has a significant cross-border trade economy.', '["Seme border crossing","Cross-border trade","Border communities"]'::jsonb),
  ('epe-lcda', 'Epe LCDA', 'epe', 'Epe', 'Hon. Bolaji Makinde', NULL, 'Epe LCDA Secretariat, Epe, Lagos', '+234-1-4930710', NULL, 'Suburban', '2002', 'Epe', NULL, NULL, '{"lat":6.5864,"lng":3.9779}'::jsonb, 'Epe LCDA covers the historic Epe town on the Lekki Lagoon. The area is known for fishing, the Ojude Oba festival and its growing status as a gateway to the Lekki Free Zone.', '["Epe Fish Market","Ojude Oba Festival","Lagoon fishing","Emerging smart city"]'::jsonb),
  ('ikosi-ejinrin-lcda', 'Ikosi-Ejinrin LCDA', 'epe', 'Epe', 'Hon. Saheed Afolabi', NULL, 'Ikosi-Ejinrin LCDA Secretariat, Ejinrin, Lagos', '+234-1-4930720', NULL, 'Suburban', '2002', 'Ejinrin', NULL, NULL, '{"lat":6.53,"lng":3.85}'::jsonb, 'Ikosi-Ejinrin LCDA covers the Ejinrin and Ikosi communities on the Lagos-Epe Expressway corridor. The area has significant agricultural and fishing activity.', '["Agricultural communities","Lagos-Epe corridor","Fishing lagoon communities"]'::jsonb),
  ('ikoyi-obalende-lcda', 'Ikoyi-Obalende LCDA', 'eti-osa', 'Eti-Osa', 'Hon. Ade Adewale', NULL, 'Ikoyi-Obalende LCDA Secretariat, Ikoyi, Lagos', '+234-1-4930810', NULL, 'Island', '2002', 'Ikoyi', NULL, NULL, '{"lat":6.453,"lng":3.428}'::jsonb, 'Ikoyi-Obalende LCDA covers two of Lagos''s most iconic neighbourhoods. Ikoyi is one of Nigeria''s most exclusive residential and diplomatic enclaves while Obalende is a major transport interchange connecting Lagos Island to the Mainland.', '["Luxury residences","Diplomatic quarters","Obalende bus terminal","Falomo Bridge"]'::jsonb),
  ('iru-victoria-island-lcda', 'Iru-Victoria Island LCDA', 'eti-osa', 'Eti-Osa', 'Hon. Kayode Fashola', NULL, 'Iru-Victoria Island LCDA Secretariat, Victoria Island, Lagos', '+234-1-4930820', NULL, 'Island', '2002', 'Victoria Island', NULL, NULL, '{"lat":6.4281,"lng":3.4219}'::jsonb, 'Iru-Victoria Island LCDA covers Victoria Island — Nigeria''s premier business and entertainment district. Home to multinational corporations, five-star hotels, embassies and the Eko Atlantic City development.', '["Multinational HQs","Eko Atlantic City","Fine dining","Bar Beach","Embassies"]'::jsonb),
  ('lagos-island-east-lcda', 'Lagos Island East LCDA', 'eti-osa', 'Eti-Osa', 'Hon. Tunde Dosunmu', NULL, 'Lagos Island East LCDA Secretariat, Lekki, Lagos', '+234-1-4930830', NULL, 'Island', '2002', 'Lekki Phase 1', NULL, NULL, '{"lat":6.435,"lng":3.475}'::jsonb, 'Lagos Island East LCDA covers Lekki Phase 1 and its surroundings — one of the fastest-growing luxury residential and commercial areas in Lagos, with renowned restaurants, art galleries and tech offices.', '["Lekki Phase 1","Nike Art Gallery","Upscale dining","Tech offices"]'::jsonb),
  ('ibeju-lcda', 'Ibeju LCDA', 'ibeju-lekki', 'Ibeju-Lekki', 'Hon. Sola Adeleke', NULL, 'Ibeju LCDA Secretariat, Akodo, Lagos', '+234-1-4930910', NULL, 'Suburban', '2002', 'Akodo', NULL, NULL, '{"lat":6.4353,"lng":3.8087}'::jsonb, 'Ibeju LCDA covers the western part of Ibeju-Lekki including the Dangote Refinery site and the Lekki Deep Sea Port. It is the epicentre of Nigeria''s industrial transformation.', '["Dangote Refinery","Lekki Deep Sea Port","Industrial zone","Investment hub"]'::jsonb),
  ('lekki-lcda', 'Lekki LCDA', 'ibeju-lekki', 'Ibeju-Lekki', 'Hon. Rotimi Ajakaye', NULL, 'Lekki LCDA Secretariat, Lekki Free Zone, Lagos', '+234-1-4930920', NULL, 'Suburban', '2002', 'Lekki Free Zone', NULL, NULL, '{"lat":6.45,"lng":3.95}'::jsonb, 'Lekki LCDA covers the Lekki Free Trade Zone and surrounding beach communities. It is home to the La Campagne Tropicana resort and Eleko Beach, making it both an industrial and tourism destination.', '["Lekki Free Zone","La Campagne Tropicana","Eleko Beach","Tourism & industry"]'::jsonb),
  ('ifako-ijaye-lcda', 'Ifako-Ijaye LCDA', 'ifako-ijaiye', 'Ifako-Ijaiye', 'Hon. Ayo Bankole', NULL, 'Ifako-Ijaye LCDA Secretariat, Ogba, Lagos', '+234-1-4931010', NULL, 'Mainland', '2002', 'Ogba', NULL, NULL, '{"lat":6.6463,"lng":3.3404}'::jsonb, 'Ifako-Ijaye LCDA covers the Ogba commercial district and Ifako residential areas. Ogba is one of Lagos''s most thriving middle-class neighbourhoods with shopping malls, schools and businesses.', '["Ogba Shopping District","Middle-class residences","Commercial hub"]'::jsonb),
  ('ojokoro-lcda', 'Ojokoro LCDA', 'ifako-ijaiye', 'Ifako-Ijaiye', 'Hon. Biodun Ogunwale', NULL, 'Ojokoro LCDA Secretariat, Agbado, Lagos', '+234-1-4931020', NULL, 'Mainland', '2002', 'Agbado', NULL, NULL, '{"lat":6.66,"lng":3.29}'::jsonb, 'Ojokoro LCDA covers the Agbado-Ojokoro corridor near the Ogun State border. The area has significant railway heritage and is a growing commuter community.', '["Agbado railway junction","Border community","Commuter suburb"]'::jsonb),
  ('ojodu-lcda', 'Ojodu LCDA', 'ikeja', 'Ikeja', 'Hon. Segun Odunmbaku', NULL, 'Ojodu LCDA Secretariat, Ojodu, Lagos', '+234-1-4931110', NULL, 'Mainland', '2002', 'Ojodu', NULL, NULL, '{"lat":6.635,"lng":3.355}'::jsonb, 'Ojodu LCDA covers the Ojodu-Berger area, one of Lagos''s busiest transport interchanges connecting the Mainland to Ogun State. The area hosts the Lagos State Public Works Corporation headquarters.', '["Berger Bus Stop","Transport interchange","LSPWC headquarters","Residential estates"]'::jsonb),
  ('onigbongbo-lcda', 'Onigbongbo LCDA', 'ikeja', 'Ikeja', 'Hon. Tunde Aromolewa', NULL, 'Onigbongbo LCDA Secretariat, Maryland, Lagos', '+234-1-4931120', NULL, 'Mainland', '2002', 'Maryland', NULL, NULL, '{"lat":6.57,"lng":3.36}'::jsonb, 'Onigbongbo LCDA covers the Maryland-Ikeja axis, home to the Murtala Muhammed Airport, Computer Village and the Ikeja GRA. This is the administrative and commercial heart of Lagos State.', '["Murtala Muhammed Airport","Computer Village","Ikeja GRA","Maryland Mall"]'::jsonb),
  ('ikorodu-north-lcda', 'Ikorodu North LCDA', 'ikorodu', 'Ikorodu', 'Hon. Lekan Fatodu', NULL, 'Ikorodu North LCDA Secretariat, Ikorodu, Lagos', '+234-1-4931210', NULL, 'Suburban', '2002', 'Ikorodu North', NULL, NULL, '{"lat":6.65,"lng":3.52}'::jsonb, 'Ikorodu North LCDA covers the northern part of the Ikorodu urban area. It has significant agricultural land and is a gateway to the Lagos-Ibadan Expressway via Sagamu-Ore Road.', '["Agricultural communities","Sagamu Road corridor","Residential growth"]'::jsonb),
  ('ikorodu-west-lcda', 'Ikorodu West LCDA', 'ikorodu', 'Ikorodu', 'Hon. Yetunde Adewale', NULL, 'Ikorodu West LCDA Secretariat, Ikorodu, Lagos', '+234-1-4931220', NULL, 'Suburban', '2002', 'Ikorodu West', NULL, NULL, '{"lat":6.61,"lng":3.49}'::jsonb, 'Ikorodu West LCDA covers the western section of the Ikorodu municipality, closest to the Lagos Lagoon ferry terminal.', '["Ferry terminal","Lagoon communities","Transport hub"]'::jsonb),
  ('igbogbo-bayeku-lcda', 'Igbogbo-Bayeku LCDA', 'ikorodu', 'Ikorodu', 'Hon. Rotimi Adesanya', NULL, 'Igbogbo-Bayeku LCDA Secretariat, Igbogbo, Lagos', '+234-1-4931230', NULL, 'Suburban', '2002', 'Igbogbo', NULL, NULL, '{"lat":6.59,"lng":3.54}'::jsonb, 'Igbogbo-Bayeku LCDA covers the Igbogbo and Bayeku lagoon communities, known for fishing and small-scale aquaculture.', '["Fishing communities","Aquaculture","Lagoon lifestyle"]'::jsonb),
  ('imota-lcda', 'Imota LCDA', 'ikorodu', 'Ikorodu', 'Hon. Mulikat Efuwape', NULL, 'Imota LCDA Secretariat, Imota, Lagos', '+234-1-4931240', NULL, 'Suburban', '2002', 'Imota', NULL, NULL, '{"lat":6.64,"lng":3.6}'::jsonb, 'Imota LCDA is home to the Dangote Rice Mill — one of the largest rice processing plants in Africa — which has transformed the local economy significantly.', '["Dangote Rice Mill","Agricultural processing","Rural farming"]'::jsonb),
  ('ikosi-isheri-lcda', 'Ikosi-Isheri LCDA', 'ikorodu', 'Ikorodu', 'Hon. Femi Owolade', NULL, 'Ikosi-Isheri LCDA Secretariat, Ikosi, Lagos', '+234-1-4931250', NULL, 'Suburban', '2002', 'Ikosi', NULL, NULL, '{"lat":6.62,"lng":3.46}'::jsonb, 'Ikosi-Isheri LCDA covers the Ikosi and Isheri communities at the southern tip of Ikorodu, bordering Kosofe LGA. The area has growing residential estates.', '["Residential growth","Isheri waterway","Southern Ikorodu"]'::jsonb),
  ('kosofe-lcda', 'Kosofe LCDA', 'kosofe', 'Kosofe', 'Hon. Segun Adewale', NULL, 'Kosofe LCDA Secretariat, Ogudu, Lagos', '+234-1-4931310', NULL, 'Mainland', '2002', 'Ogudu', NULL, NULL, '{"lat":6.5833,"lng":3.4167}'::jsonb, 'Kosofe LCDA covers Ogudu, Ojota and surrounding communities. The Ojota transport interchange is one of the busiest in Lagos, serving routes across the Mainland and beyond.', '["Ojota bus terminal","Ogudu GRA","Transport hub","NASFAT HQ"]'::jsonb),
  ('agboyi-ketu-lcda', 'Agboyi-Ketu LCDA', 'kosofe', 'Kosofe', 'Hon. Tunji Olawale', NULL, 'Agboyi-Ketu LCDA Secretariat, Ketu, Lagos', '+234-1-4931320', NULL, 'Mainland', '2002', 'Ketu', NULL, NULL, '{"lat":6.597,"lng":3.387}'::jsonb, 'Agboyi-Ketu LCDA covers the Ketu and Mile 12 communities. Mile 12 International Market is one of the largest fresh produce markets in West Africa, serving as the primary food distribution hub for Lagos.', '["Mile 12 produce market","Ketu bus terminal","Food distribution hub"]'::jsonb),
  ('yaba-lcda', 'Yaba LCDA', 'lagos-mainland', 'Lagos Mainland', 'Hon. Babatunde Gbadamosi', NULL, 'Yaba LCDA Secretariat, Yaba, Lagos', '+234-1-4931510', NULL, 'Mainland', '2002', 'Yaba', NULL, NULL, '{"lat":6.5095,"lng":3.3711}'::jsonb, 'Yaba LCDA covers Yaba, Ebute Metta, Makoko and Sabo. Yaba is Nigeria''s premier technology ecosystem and educational hub hosting CcHub, dozens of startups and several universities. Makoko is Africa''s most photographed floating community.', '["Yaba tech hub","CcHub Nigeria","UNILAG proximity","Makoko floating village","YABATECH"]'::jsonb),
  ('mushin-lcda', 'Mushin LCDA', 'mushin', 'Mushin', 'Hon. Ayo Olatunji', NULL, 'Mushin LCDA Secretariat, Mushin, Lagos', '+234-1-4931610', NULL, 'Mainland', '2002', 'Mushin', NULL, NULL, '{"lat":6.5277,"lng":3.3561}'::jsonb, 'Mushin LCDA covers the core Mushin township, one of Lagos''s most commercially vibrant working-class communities. The area is famous for Ladipo auto-parts market and its rich musical heritage.', '["Ladipo Auto Market","Music culture","Commercial markets","Urban resilience"]'::jsonb),
  ('odi-olowo-ojuwoye-lcda', 'Odi-Olowo/Ojuwoye LCDA', 'mushin', 'Mushin', 'Hon. Taofeeq Animasaun', NULL, 'Odi-Olowo LCDA Secretariat, Idi-Araba, Lagos', '+234-1-4931620', NULL, 'Mainland', '2002', 'Idi-Araba', NULL, NULL, '{"lat":6.515,"lng":3.35}'::jsonb, 'Odi-Olowo/Ojuwoye LCDA covers the area around Idi-Araba and the LUTH hospital district. It borders Surulere and has a mix of residential and medical service communities.', '["LUTH proximity","Medical corridor","Residential community"]'::jsonb),
  ('ojo-lcda', 'Ojo LCDA', 'ojo', 'Ojo', 'Hon. Damola Adesanya', NULL, 'Ojo LCDA Secretariat, Ojo, Lagos', '+234-1-4931710', NULL, 'Mainland', '2002', 'Ojo', NULL, NULL, '{"lat":6.4698,"lng":3.2067}'::jsonb, 'Ojo LCDA covers the Ojo township and military cantonment areas. The area hosts Lagos State University''s main campus and the Ojo Military Cantonment — one of the largest in Nigeria.', '["LASU Campus","Ojo Military Cantonment","Badagry Expressway","Atlantic coastline"]'::jsonb),
  ('oto-awori-lcda', 'Oto-Awori LCDA', 'ojo', 'Ojo', 'Hon. Tunde Fatula', NULL, 'Oto-Awori LCDA Secretariat, Oto-Awori, Lagos', '+234-1-4931720', NULL, 'Mainland', '2002', 'Oto-Awori', NULL, NULL, '{"lat":6.4,"lng":3.15}'::jsonb, 'Oto-Awori LCDA covers the indigenous Awori communities in the western part of Ojo LGA along the Lagos-Badagry Expressway. These are among the oldest native settlements in the Lagos area.', '["Awori indigenous communities","Coastal fishing","Ancient settlements","Expressway corridor"]'::jsonb),
  ('ejigbo-lcda', 'Ejigbo LCDA', 'oshodi-isolo', 'Oshodi-Isolo', 'Hon. Muyiwa Agunbiade', NULL, 'Ejigbo LCDA Secretariat, Ejigbo, Lagos', '+234-1-4931810', NULL, 'Mainland', '2002', 'Ejigbo', NULL, NULL, '{"lat":6.51,"lng":3.32}'::jsonb, 'Ejigbo LCDA covers the Ejigbo and Ishaga communities in the southern part of Oshodi-Isolo LGA. The area has significant residential estates and light industrial activity.', '["Residential estates","Light industry","Expressway corridor"]'::jsonb),
  ('bariga-lcda', 'Bariga LCDA', 'shomolu', 'Shomolu', 'Hon. Lanre Adeyemi', NULL, 'Bariga LCDA Secretariat, Bariga, Lagos', '+234-1-4931910', NULL, 'Mainland', '2002', 'Bariga', NULL, NULL, '{"lat":6.53,"lng":3.39}'::jsonb, 'Bariga LCDA covers the Bariga waterfront community on the edge of the Lagos Lagoon. The area has a vibrant creative scene and strong community associations.', '["Waterfront community","Creative culture","Lagoon access","Bariga market"]'::jsonb),
  ('shomolu-lcda', 'Shomolu LCDA', 'shomolu', 'Shomolu', 'Hon. Olumide Abiodun', NULL, 'Shomolu LCDA Secretariat, Shomolu, Lagos', '+234-1-4931920', NULL, 'Mainland', '2002', 'Shomolu', NULL, NULL, '{"lat":6.5356,"lng":3.3861}'::jsonb, 'Shomolu LCDA covers the Shomolu and Gbagada communities. Gbagada is one of Lagos''s most desirable middle-class residential areas with well-maintained roads and strong estate culture.', '["Gbagada Estate","Residential quality","Third Mainland Bridge access","Anthony Village"]'::jsonb),
  ('itire-ikate-lcda', 'Itire-Ikate LCDA', 'surulere', 'Surulere', 'Hon. Babatunde Adeyemo', NULL, 'Itire-Ikate LCDA Secretariat, Itire, Lagos', '+234-1-4932010', NULL, 'Mainland', '2002', 'Itire', NULL, NULL, '{"lat":6.48,"lng":3.35}'::jsonb, 'Itire-Ikate LCDA covers the Itire and Ikate communities on the boundary of Surulere and Eti-Osa. The area bridges the creative Surulere culture with the commercial Lekki axis.', '["Boundary community","Itire market","Mixed-use development"]'::jsonb),
  ('surulere-lcda', 'Surulere LCDA', 'surulere', 'Surulere', 'Hon. Gbadebo Akosile', NULL, 'Surulere LCDA Secretariat, Surulere, Lagos', '+234-1-4932020', NULL, 'Mainland', '2002', 'Surulere', NULL, NULL, '{"lat":6.4969,"lng":3.3481}'::jsonb, 'Surulere LCDA covers the core Surulere township — home to the National Stadium, Teslim Balogun Stadium, National Theatre and LUTH. This is Lagos''s cultural and sporting heartland.', '["National Stadium","National Theatre","LUTH","Fela Kuti heritage","Adeniran Ogunsanya Street"]'::jsonb)
